import{_ as t,o as r,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Optimize librbd for Lower CPU Cost and Higher Scalability - Li Wang, DiDi","description":"","frontmatter":{"title":"Optimize librbd for Lower CPU Cost and Higher Scalability - Li Wang, DiDi","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","librbd","性能优化","CPU开销","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Optimize_librbd_for_Lower_CPU_Cost_and_Higher_Scalability_-_Li_Wang_DiDi.md","filePath":"posts/2019/Optimize_librbd_for_Lower_CPU_Cost_and_Higher_Scalability_-_Li_Wang_DiDi.md","lastUpdated":1780459816000}'),o={name:"posts/2019/Optimize_librbd_for_Lower_CPU_Cost_and_Higher_Scalability_-_Li_Wang_DiDi.md"};function _(a,i,s,n,p,g){return r(),e("div",null,[...i[0]||(i[0]=[l("<p>会议纪要</p><p>会议时间：[请填写会议时间] 会议地点：[请填写会议地点] 参会人员：[请填写参会人员名单] 主持人：[请填写主持人姓名]</p><p>一、会议内容</p><ol><li><p><strong>Liberty优化工作分享</strong></p><p>主持人来自PD云存储团队，介绍了Liberty优化工作的进展，主要包括以下内容：</p><ul><li><strong>Liberty架构概述</strong>：Liberty是Ceph的一个分布式存储解决方案，适用于虚拟化场景，其数据流涉及磁盘访问请求、OSD、CRUSH算法等。</li><li><strong>IBD LPS优化</strong>：针对IBD LPS在随机写测试中不随集群规模扩展的问题，提出了并行化闪存工作、优化单线程设计为多线程设计等解决方案。</li><li><strong>客户端镜像缓存</strong>：利用Ceph的快照功能，通过优化镜像缓存机制，提高虚拟机启动速度。</li><li><strong>写操作CPU开销优化</strong>：提出升级Ceph版本、使用新的API调用方式等优化方案，以降低Liberty导致的CPU使用率过高问题。</li><li><strong>数据恢复优化</strong>：介绍数据恢复过程中的优化策略，包括使用Rebalance优化请求逻辑、回调机制等。</li></ul></li><li><p><strong>社区合作与经验分享</strong></p><p>主持人分享了与社区合作的经验和遇到的问题：</p><ul><li><strong>Liberty延迟问题</strong>：Liberty在SSD和NVMe存储上的延迟较高，可能影响数据库等对延迟敏感的应用。</li><li><strong>硬件利用率问题</strong>：当平均负载超过60%时，可能出现延迟和缓慢请求。</li><li><strong>价格与性能平衡</strong>：社区在硬件优化方面投入较多，但客户更关注价格和性能平衡。</li><li><strong>CPU使用率问题</strong>：Liberty导致CPU使用率过高，限制了SSD的性能。</li></ul></li></ol><p>二、会议决定</p><ol><li>与社区合作，共同优化Liberty性能，特别是延迟、硬件利用率和CPU使用率等问题。</li><li>探索新的优化方案，提高Liberty在虚拟化场景下的性能和稳定性。</li></ol><p>三、后续行动计划</p><ol><li>优化Liberty代码，提高性能和稳定性。</li><li>与社区合作，共同解决Liberty在虚拟化场景下的性能瓶颈。</li><li>收集用户反馈，持续改进Liberty产品。</li></ol><p>改进后的总结更准确地反映了原始内容的要点，包括会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。同时，保留了相关的Ceph领域英文关键词，如librbd、Ceph、CRUSH algorithm、OSD等。</p>",9)])])}const C=t(o,[["render",_]]);export{d as __pageData,C as default};
